223:
SELECT DISTINCT c."atom_id"
FROM "connected" c
WHERE c."bond_id" = 'TR000_2_5';

699:
SELECT u."creationdate"
FROM "users" u
WHERE u."displayname" LIKE 'IrishStat';

588:
SELECT COUNT(*) AS total_comments
FROM "comments" c
WHERE c."userid"::BIGINT = 13;

589:
SELECT "id"
FROM "users"
WHERE "reputation"::BIGINT = (
    SELECT MAX("reputation"::BIGINT)
    FROM "users"
);

572:
SELECT p."viewcount"
FROM "posts" p
WHERE p."title" LIKE '%Integration of Weka and/or RapidMiner into Informatica PowerCenter/Developer%';

747:
SELECT COUNT(*) AS total_superheroes_without_full_name
FROM "superhero" s
WHERE s."full_name" IS NULL;

1377:
SELECT COUNT(*) AS president_count
FROM "member" m
WHERE LOWER(m."position") = 'president';

1436:
SELECT DISTINCT e."link_to_event"
FROM expense e
WHERE CAST(e."cost" AS REAL) > 50;

1365:
SELECT e."expense_description"
FROM "expense" e
JOIN "budget" b ON e."link_to_budget" = b."budget_id"
WHERE b."remaining"::NUMERIC = (
    SELECT MIN("remaining"::NUMERIC) FROM "budget"
);
